// 실행 시점(KST)에 따라 수집 시간 창을 계산한다.
const KST = 9 * 3600 * 1000;
const nowMs = Date.now();
const kst = new Date(nowMs + KST);          // UTC 필드를 읽으면 KST 벽시계 값
const y = kst.getUTCFullYear();
const mo = kst.getUTCMonth();
const d = kst.getUTCDate();
const dow = kst.getUTCDay();                 // 0=일 ... 1=월 ... 5=금

// KST 특정 날짜 06:00 의 epoch(초)
function kst6(Y, M, D) {
  return Math.floor(Date.UTC(Y, M, D, 6 - 9, 0, 0) / 1000); // 06:00 KST = (06-09)h UTC
}

const end = kst6(y, mo, d);                  // 오늘 06:00 KST
let start, runType;
if (dow === 1) {                             // 월요일 → 주말분
  start = end - 3 * 86400;                   // 지난 금 06:00
  runType = '주말분 (금 06:00 → 월 06:00)';
} else if (dow === 5) {                       // 금요일 → 주중분
  start = end - 4 * 86400;                   // 이번 월 06:00
  runType = '주중분 (월 06:00 → 금 06:00)';
} else {                                      // 수동 테스트
  start = Math.floor(nowMs / 1000) - 2 * 86400;
  runType = '수동 실행 (최근 48시간)';
}

function fmt(epoch) {
  const dd = new Date(epoch * 1000 + KST);
  const M = dd.getUTCMonth() + 1, D = dd.getUTCDate();
  const h = String(dd.getUTCHours()).padStart(2, '0');
  const mi = String(dd.getUTCMinutes()).padStart(2, '0');
  return `${M}.${D} ${h}:${mi}`;
}
const WD = ['일','월','화','수','목','금','토'];

return [{
  json: {
    q: 'in:inbox',
    startISO: new Date(start * 1000).toISOString(),
    endISO: new Date(end * 1000).toISOString(),
    end,
    runType,
    rangeLabel: `${fmt(start)} – ${fmt(end)} KST`,
    runDateLabel: `${mo + 1}.${d} (${WD[dow]})`,
    selfEmail: 'soobin7612@gmail.com'   // ← 받는 사람(본인). 필요시 변경
  }
}];

const win = $('Compute Window').first().json;
const items = $input.all();
const TEMPLATE = Buffer.from("", "base64").toString("utf8");

function header(msg, name) {
  const hs = (msg.payload && msg.payload.headers) || [];
  const h = hs.find(x => x.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : '';
}
function parseFrom(v) {
  const m = v.match(/^(.*?)<([^>]+)>\s*$/);
  if (m) return { name: (m[1].replace(/"/g, '').trim() || m[2].trim()), email: m[2].trim() };
  return { name: v.trim(), email: v.trim() };
}
function esc(s) { return (s || '').replace(/[\u0000-\u001F]/g, ' ').trim(); }

// 자동 분류: 노이즈(뉴스레터/보안/공지/학습/기회)는 패턴으로 잡고,
// 그 외 '사람이 보낸 듯한' 메일은 확인필요(action)로 격상한다.
function classify(name, email, subj) {
  const hay = (email + ' ' + subj + ' ' + name).toLowerCase();
  const has = (...ks) => ks.some(k => hay.includes(k));
  if (has('accounts.google.com', '보안 알림', 'security alert', 'new sign-in', 'sign-in', '로그인'))
    return { cat: 'security', prio: 'low' };
  if (has('scholar', 'coursera', 'inflearn', 'elice', 'goorm', '녹화본', '강의', 'webinar', 'course', 'lecture'))
    return { cat: 'study', prio: 'mid' };
  if (has('outlier', 'recruit', 'hiring', 'mission', '채용'))
    return { cat: 'outlier', prio: 'low' };
  if (has('개인정보', '약관', '처리방침', 'policy', 'terms'))
    return { cat: 'account', prio: 'mid' };
  if (has('no-reply', 'noreply', 'newsletter', 'beehiiv', 'mailchimp', 'substack', 'mailer',
          '광고', 'digest', 'unsubscribe', 'marketing', 'promo', 'sale', '뉴스레터'))
    return { cat: 'news', prio: 'low' };
  return { cat: 'action', prio: 'high' };
}

const recs = [];
for (const it of items) {
  const msg = it.json;
  const labels = msg.labelIds || [];
  if (labels.includes('SENT') && !labels.includes('INBOX')) continue;
  const { name, email } = parseFrom(header(msg, 'From'));
  const subj = esc(header(msg, 'Subject'));
  const snip = esc(msg.snippet || '').slice(0, 160);
  const date = msg.internalDate
    ? new Date(parseInt(msg.internalDate, 10)).toISOString()
    : new Date(header(msg, 'Date') || Date.now()).toISOString();
  const c = classify(name, email, subj);
  recs.push({ from: name, email, subj, snip, date, cat: c.cat, prio: c.prio, unread: labels.includes('UNREAD') });
}

const rank = { high: 0, mid: 1, low: 2 };
recs.sort((a, b) => {
  if ((a.cat === 'action') !== (b.cat === 'action')) return a.cat === 'action' ? -1 : 1;
  if (rank[a.prio] !== rank[b.prio]) return rank[a.prio] - rank[b.prio];
  return new Date(b.date) - new Date(a.date);
});

const total = recs.length;
const actionN = recs.filter(r => r.cat === 'action').length;
const unreadN = recs.filter(r => r.unread).length;
const newsN = recs.filter(r => r.cat === 'news').length;

// 인터랙티브 대시보드 (첨부)
const dash = TEMPLATE
  .replace('{{TITLE}}', 'Inbox Triage · ' + win.rangeLabel)
  .replace('{{EYEBROW}}', 'Inbox Triage · ' + win.selfEmail)
  .replace('{{HEADING}}', '수신 메일 대시보드')
  .replace('{{SUBTITLE}}', win.rangeLabel + ' · ' + win.runType)
  .replace('{{FOOTER}}', '자동 생성 · ' + win.runDateLabel + ' · 발신 메일 제외 · 시간 KST')
  .replace('/*__MAILS_DATA__*/[]', JSON.stringify(recs));

// 정적 요약 (이메일 본문, JS 없음)
const CL = { action: '확인필요', account: '계정·공지', study: '학습·강의', outlier: '기회·제안', security: '보안', news: '뉴스레터' };
const CC = { action: '#c0392b', account: '#1f7a8c', study: '#6a4c93', outlier: '#b8860b', security: '#9aa0ab', news: '#8a93a3' };
const rowOf = (r) => `<tr>
  <td style="padding:6px 10px;border-bottom:1px solid #eee;white-space:nowrap;"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${CC[r.cat]};margin-right:6px;"></span>${CL[r.cat]}</td>
  <td style="padding:6px 10px;border-bottom:1px solid #eee;font-weight:${r.unread ? '700' : '400'};white-space:nowrap;">${r.from}</td>
  <td style="padding:6px 10px;border-bottom:1px solid #eee;color:#333;">${r.subj}</td></tr>`;
const aRows = recs.filter(r => r.cat === 'action').map(rowOf).join('') || '<tr><td colspan="3" style="padding:8px 10px;color:#888;">확인필요 메일 없음</td></tr>';
const oRows = recs.filter(r => r.cat !== 'action' && r.cat !== 'news').map(rowOf).join('') || '<tr><td colspan="3" style="padding:8px 10px;color:#888;">없음</td></tr>';

const summary = `<div style="font-family:-apple-system,'Apple SD Gothic Neo',sans-serif;max-width:680px;color:#161a22;">
  <h2 style="margin:0 0 4px;">수신 메일 대시보드</h2>
  <p style="color:#666;margin:0 0 16px;">${win.rangeLabel} · ${win.runType}</p>
  <p style="margin:0 0 16px;font-size:15px;">전체 <b>${total}</b>건 · 확인필요 <b style="color:#c0392b;">${actionN}</b>건 · 안읽음 <b>${unreadN}</b>건 · 뉴스레터 ${newsN}건</p>
  <h3 style="margin:18px 0 6px;color:#c0392b;">확인 필요</h3>
  <table style="border-collapse:collapse;width:100%;font-size:13px;">${aRows}</table>
  <h3 style="margin:18px 0 6px;">계정 · 학습 · 기타</h3>
  <table style="border-collapse:collapse;width:100%;font-size:13px;">${oRows}</table>
  <p style="color:#888;font-size:12px;margin-top:18px;">전체 목록 · 검색 · 카테고리 필터는 첨부된 HTML 대시보드를 브라우저로 열어 확인하세요.</p>
</div>`;

const stamp = new Date(win.end * 1000 + 9 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');
return [{
  json: {
    selfEmail: win.selfEmail,
    subject: `[수신 메일] ${win.runDateLabel} · 전체 ${total} / 확인필요 ${actionN}`,
    summary
  },
  binary: {
    data: { data: Buffer.from(dash, 'utf8').toString('base64'), mimeType: 'text/html', fileName: `inbox-${stamp}.html` }
  }
}];
